Un mapa de cultivos marca con 1 las parcelas con plaga. Se quiere contar los focos, donde un foco son parcelas con plaga pegadas arriba, abajo, izquierda o derecha.

function contarFocos(mapa) {
  const vistas = mapa.map((f) => f.map(() => false));
  let focos = 0;
  function seguir(r, c) {
    if (r < 0 || c < 0 || r >= mapa.length || c >= mapa[r].length) return;
    if (mapa[r][c] !== 1 || vistas[r][c]) return;
    vistas[r][c] = true;
    seguir(r + 1, c);
    seguir(r - 1, c);
    seguir(r, c + 1);
    seguir(r, c - 1);
  }
  for (let r = 0; r < mapa.length; r++) {
    for (let c = 0; c < mapa[r].length; c++) {
      if (mapa[r][c] === 1 && !vistas[r][c]) { focos++; seguir(r, c); }
    }
  }
  return focos;
}
